from sessions import count_sessions
from summary import render


def test_single_session_within_gaps():
    events = [("u1", 0), ("u1", 600), ("u1", 1200)]
    assert count_sessions(events) == {"u1": 1}


def test_gap_over_threshold_starts_new_session():
    events = [("u1", 0), ("u1", 2000), ("u1", 2500)]
    assert count_sessions(events) == {"u1": 2}


def test_exactly_1800_stays_same_session():
    events = [("u1", 0), ("u1", 1800)]
    assert count_sessions(events) == {"u1": 1}


def test_multiple_users_and_unsorted_input():
    # u1's events arrive out of order (5000 before 0); a correct impl sorts
    # each user's timestamps before measuring gaps.
    events = [("u1", 5000), ("u2", 100), ("u1", 0), ("u2", 200)]
    assert count_sessions(events) == {"u1": 2, "u2": 1}


def test_skips_invalid_events():
    events = [("u1", 0), ("", 100), ("u1", "bad"), ("u1", True), ("u1", 100)]
    assert count_sessions(events) == {"u1": 1}


def test_render_integration():
    events = [("u1", 0), ("u1", 5000), ("u2", 0)]
    assert render(events) == "u1: 2\nu2: 1"

