def count_sessions(events):
    """Number of sessions per user; a >1800s gap starts a new session."""
    by_user = {}
    for ev in events:
        if not isinstance(ev, (list, tuple)) or len(ev) < 2:
            continue
        user, ts = ev[0], ev[1]
        if not isinstance(user, str) or user.strip() == "":
            continue
        if not isinstance(ts, int) or isinstance(ts, bool):
            continue
        by_user.setdefault(user, []).append(ts)

    counts = {}
    for user, times in by_user.items():
        times.sort()
        sessions = 0
        prev = None
        for t in times:
            if prev is None or t - prev > 1800:
                sessions += 1
            prev = t
        counts[user] = sessions
    return counts

